        static constexpr DataModel::AcceptedCommandEntry kCommands[] = {
            { ResourceMonitoring::Commands::ResetCondition::kMetadataEntry }
        };
        ReturnErrorOnFailure(builder.ReferenceExisting(kCommands));
    }

